class Solution {
    public int countKDifference(int[] nums, int k) {
        int pairs = 0;
        for (int i = 0; i < nums.length; i++) {
            for (int j = i + 1; j < nums.length; j++) {
                if (Math.abs(nums[i] - nums[j]) == k) {
                    pairs++;
                }
            }
        }
        return pairs;
    }
}

class Solution {
    public int countKDifference(int[] nums, int k) {
        int[] seen = new int[101];
        int pairs = 0;
        for (int num : nums) {
            if (num - k >= 1) {
                pairs += seen[num - k];
            }
            if (num + k <= 100) {
                pairs += seen[num + k];
            }
            seen[num]++;
        }
        return pairs;
    }
}

class Solution {
    public int countKDifference(int[] nums, int k) {
        int[] frequency = new int[101];
        for (int num : nums) {
            frequency[num]++;
        }

        int pairs = 0;
        for (int value = 1; value + k <= 100; value++) {
            pairs += frequency[value] * frequency[value + k];
        }
        return pairs;
    }
}

import java.util.Arrays;

class Solution {
    public int countKDifference(int[] nums, int k) {
        Arrays.sort(nums);
        int left = 0;
        int right = 1;
        int pairs = 0;
        while (left < nums.length && right < nums.length) {
            if (left == right) {
                right++;
                continue;
            }
            int diff = nums[right] - nums[left];
            if (diff < k) {
                right++;
            } else if (diff > k) {
                left++;
            } else {
                int leftValue = nums[left];
                int rightValue = nums[right];
                int leftCount = 0;
                while (left < nums.length && nums[left] == leftValue) {
                    left++;
                    leftCount++;
                }
                int rightCount = 0;
                while (right < nums.length && nums[right] == rightValue) {
                    right++;
                    rightCount++;
                }
                pairs += leftCount * rightCount;
            }
            if (right <= left) {
                right = left + 1;
            }
        }
        return pairs;
    }
}
